// Generates supabase/seed.sql from scripts/seed-data.mjs.
// Usage: npm run seed:build
// The generated file is safe to run more than once: every row has a fixed id and uses "on conflict (id) do update".

import { writeFileSync, mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { buildRows } from "./seed-data.mjs";

const here = dirname(fileURLToPath(import.meta.url));
const out = resolve(here, "../supabase/seed.sql");

const q = (value) => {
  if (value === null || value === undefined) return "null";
  if (typeof value === "boolean") return value ? "true" : "false";
  if (typeof value === "number") return String(value);
  if (typeof value === "object") return `'${JSON.stringify(value).replace(/'/g, "''")}'::jsonb`;
  return `'${String(value).replace(/'/g, "''")}'`;
};

function upsert(table, columns, rows, conflict = "id") {
  if (!rows.length) return "";
  const updates = columns.filter((c) => !conflict.split(",").map((s) => s.trim()).includes(c));
  const values = rows.map((r) => `  (${columns.map((c) => q(r[c])).join(", ")})`).join(",\n");
  const action = updates.length ? `do update set ${updates.map((c) => `${c} = excluded.${c}`).join(", ")}` : "do nothing";
  return `insert into public.${table} (${columns.join(", ")}) values\n${values}\non conflict (${conflict}) ${action};\n`;
}

const rows = buildRows();

const lessons = rows.lessons.map((l) => ({ ...l, estimated_minutes: l.estimated_minutes ?? l.minutes ?? 5 }));

const parts = [
  "-- LINGUA starter content. GENERATED by scripts/build-seed.mjs. Do not edit by hand: change scripts/seed-data.mjs and run `npm run seed:build`.",
  "-- Run this in the Supabase SQL editor AFTER the three migrations. It is safe to run again.",
  "",
  upsert("languages", ["id", "code", "name", "native_name", "greeting", "speech_locale", "published", "position"], rows.languages),
  upsert("courses", ["id", "language_id", "title", "description", "taught_in", "published", "position"], rows.courses),
  upsert("levels", ["id", "course_id", "code", "title", "position", "published"], rows.levels),
  upsert("units", ["id", "level_id", "title", "description", "position", "published"], rows.units),
  upsert("lessons", ["id", "unit_id", "title", "description", "grammar_note", "estimated_minutes", "position", "published"], lessons),
  upsert("exercises", ["id", "lesson_id", "type", "skill", "prompt", "instructions", "explanation", "audio_url", "content", "position"], rows.exercises),
  "-- Options are replaced so edits to seed-data.mjs never leave stale answers behind.\ndelete from public.exercise_options where exercise_id in (select id from public.exercises where lesson_id in (" +
    rows.lessons.map((l) => q(l.id)).join(", ") +
    "));",
  upsert("exercise_options", ["id", "exercise_id", "text", "match_text", "is_correct", "position"], rows.options),
  upsert(
    "vocabulary",
    ["id", "language_id", "term", "translation", "transliteration", "part_of_speech", "definition", "example_sentence", "example_translation"],
    rows.vocabulary,
  ),
  upsert("lesson_vocabulary", ["lesson_id", "vocabulary_id"], rows.lessonVocabulary, "lesson_id, vocabulary_id"),
];

mkdirSync(dirname(out), { recursive: true });
writeFileSync(out, parts.filter(Boolean).join("\n") + "\n");
console.log(
  `Wrote ${out}: ${rows.languages.length} languages, ${rows.lessons.length} lessons, ${rows.exercises.length} exercises, ${rows.options.length} options, ${rows.vocabulary.length} words.`,
);
